diff --git a/packages/workflow/src/metadata-utils.ts b/packages/workflow/src/metadata-utils.ts
index 9c35e3388..cb74cf839 100644
--- a/packages/workflow/src/metadata-utils.ts
+++ b/packages/workflow/src/metadata-utils.ts
@@ -25,14 +25,20 @@ function parseErrorResponseWorkflowMetadata(response: unknown): ISubWorkflowMeta

 export function accumulateTokenUsage(
 	context: IExecuteFunctions,
-	inputTokens: number,
-	outputTokens: number,
+	inputTokens?: number | null,
+	outputTokens?: number | null,
 ): void {
+	// Providers may omit token counts; ignore missing/invalid values instead of producing NaN
+	const input = typeof inputTokens === 'number' && Number.isFinite(inputTokens) ? inputTokens : 0;
+	const output =
+		typeof outputTokens === 'number' && Number.isFinite(outputTokens) ? outputTokens : 0;
+	if (input === 0 && output === 0) return;
+
 	const prev = context.getExecuteData()?.metadata?.tokenUsage;
 	context.setMetadata({
 		tokenUsage: {
-			inputTokens: (prev?.inputTokens ?? 0) + inputTokens,
-			outputTokens: (prev?.outputTokens ?? 0) + outputTokens,
+			inputTokens: (prev?.inputTokens ?? 0) + input,
+			outputTokens: (prev?.outputTokens ?? 0) + output,
 		},
 	});
 }
